"use client";

import "./avatar.css";

import type React from "react";

import { Avatar as BaseAvatar } from "@base-ui/react/avatar";
import { cn } from "tailwind-variants";

import { AvatarContext, useAvatarContext } from "./avatar.context";
import { avatarVariants, type AvatarVariants } from "./avatar.variants";

export type AvatarProps = AvatarVariants & React.ComponentProps<typeof BaseAvatar.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/avatar/content.md
 */
export const AvatarRoot = ({ children, className, shape, size, ...props }: AvatarProps) => {
  const slots = avatarVariants({ shape, size });

  return (
    <AvatarContext.Provider value={{ slots }}>
      <BaseAvatar.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseAvatar.Root>
    </AvatarContext.Provider>
  );
};

export type AvatarImageProps = React.ComponentProps<typeof BaseAvatar.Image>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/avatar/content.md
 */
export const AvatarImage = ({ className, ...props }: AvatarImageProps) => {
  const { slots } = useAvatarContext();
  return <BaseAvatar.Image className={cn(slots.image(), className)} {...props} />;
};

export type AvatarFallbackProps = React.ComponentProps<typeof BaseAvatar.Fallback>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/avatar/content.md
 */
export const AvatarFallback = ({ className, ...props }: AvatarFallbackProps) => {
  const { slots } = useAvatarContext();
  return <BaseAvatar.Fallback className={cn(slots.fallback(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const avatarVariants = tv({
  slots: {
    root: "avatar",
    image: "avatar__image",
    fallback: "avatar__fallback",
  },
  variants: {
    size: {
      sm: {
        root: "avatar--sm",
      },
      md: {
        root: "avatar--md",
      },
      lg: {
        root: "avatar--lg",
      },
      xl: {
        root: "avatar--xl",
      },
    },
    shape: {
      circle: {
        root: "avatar--circle",
      },
      square: {
        root: "avatar--square",
      },
      rounded: {
        root: "avatar--rounded",
      },
    },
  },
  defaultVariants: {
    size: "md",
    shape: "circle",
  },
});

export type AvatarVariants = VariantProps<typeof avatarVariants>;

"use client";

import { createContext, useContext } from "react";

import { avatarVariants } from "./avatar.variants";

export type AvatarContext = {
  slots: ReturnType<typeof avatarVariants>;
};

export const AvatarContext = createContext<AvatarContext | null>(null);

export const useAvatarContext = () => {
  const context = useContext(AvatarContext);
  return context ?? { slots: avatarVariants() };
};

.avatar {
  @apply relative inline-flex shrink-0 items-center justify-center overflow-hidden bg-muted text-muted-foreground select-none align-middle font-medium;
}

.avatar--sm {
  @apply h-8 w-8 text-xs;
}

.avatar--md {
  @apply h-10 w-10 text-sm;
}

.avatar--lg {
  @apply h-12 w-12 text-base;
}

.avatar--xl {
  @apply h-16 w-16 text-lg;
}

.avatar--circle {
  @apply rounded-full;
}

.avatar--square {
  @apply rounded-none;
}

.avatar--rounded {
  @apply rounded-lg;
}

.avatar__image {
  @apply h-full w-full object-cover;
}

.avatar__fallback {
  @apply flex h-full w-full items-center justify-center font-semibold uppercase;
}

import { AvatarFallback, AvatarImage, AvatarRoot } from "./avatar";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/avatar/content.md
 */
export const Avatar = {
  Fallback: AvatarFallback,
  Image: AvatarImage,
  Root: AvatarRoot,
};

export { AvatarFallback, AvatarImage, AvatarRoot };

export type { AvatarFallbackProps, AvatarImageProps, AvatarProps } from "./avatar";
export { AvatarContext, useAvatarContext } from "./avatar.context";
export { type AvatarVariants, avatarVariants } from "./avatar.variants";
